            <div class="PopupOverlay" id="PopUpOverlayRoom">
                <div class="Popup">
                    <h2>Create New Room</h2>
                    <p>Click save when you're done.</p>

                    <form>
                        <div class="ParentLabel">
                            <label for="SelectClass">Select Class</label>
                            <div class="custom-select" id="SelectClass">
                                <div class="select-box">Class 1</div>
                                <ul class="options">
                                    <li>Class 1</li>
                                    <li>Class 2</li>
                                    <li>Class 3</li>
                                </ul>
                            </div>
                        </div>

                        <div class="ParentLabel">
                            <label for="SelectGame">Select Game</label>
                            <div class="custom-select" id="SelectGame">
                                <div class="select-box">
                                    Introduction to AI for 8th Grade Student
                                </div>
                                <ul class="options">
                                    <li>Introduction to AI for 8th Grade Student</li>
                                    <li>Game 2</li>
                                    <li>Game 3</li>
                                </ul>
                            </div>
                        </div>

                        <div class="ParentLabel">
                            <label for="SelectStudents">Select Students</label>
                            <div class="custom-select" id="SelectStudents">
                                <div class="select-box">Mohamed Ahmad</div>
                                <ul class="options">
                                    <li>Mohamed Ahmad</li>
                                    <li>Abdulaziz Hamad</li>
                                    <li>Ali Hasan</li>
                                </ul>
                                <span style="font-size: 11px; text-decoration: underline">Abdulaziz Hamad
                                    <span style="color: red; cursor: pointer; padding-: 4px 0">x</span></span>
                            </div>
                        </div>

                        <div class="ParentLabel">
                            <label for="RoomName">Room Name</label>
                            <input type="text" id="RoomName" placeholder="Room Name" />
                        </div>

                        <div class="ParentLabel">
                            <label for="PointsPerAnswer">Points / Correct Answers</label>
                            <input type="number" id="PointsPerAnswer" placeholder="20" />
                        </div>

                        <div class="ParentLabel">
                            <label for="TimePerQuestion">Time (Sec) / Question</label>
                            <input type="number" id="TimePerQuestion" placeholder="30" />
                        </div>

                        <div class="Buttons">
                            <button type="button" class="CancelBtn" id="CancelBtn">Cancel</button>
                            <button type="submit" class="SendBtn">Create New Room</button>
                        </div>
                    </form>
                </div>
            </div>
